import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';

export function initPostProcessing(renderer: THREE.WebGLRenderer, width: number, height: number) {
    const composer = new EffectComposer(renderer);

    // 1. Render Pass (Base scene)
    composer.addPass(new RenderPass(renderer.scene, renderer.camera));

    // 2. Bloom Pass (Neon Glow)
    // Tuned for emissive surfaces to glow without washing out to white
    const bloomPass = new UnrealBloomPass(
        new THREE.Vector2(width, height),
        1.5,   // strength: Intensity of the bloom
        0.4,   // radius: Spread of the blur
        0.6    // threshold: Only bright emissive surfaces trigger bloom
    );
    composer.addPass(bloomPass);

    return composer;
}
