import * as THREE from 'three';

export class InputManager {
    private keys: Map<string, boolean> = new Map();
    private gamepadIndex: number | null = null;

    constructor() {
        window.addEventListener('keydown', (e) => this.keys.set(e.code, true));
        window.addEventListener('keyup', (e) => this.keys.delete(e.code));

        // Gamepad polling setup
        window.addEventListener("gamepadconnected", (e) => {
            console.log("Gamepad connected at index %d: %s. %d buttons, %d axes.",
                e.gamepad.index, e.gamepad.id,
                e.gamepad.buttons.length, e.gamepad.axes.length);
            this.gamepadIndex = e.gamepad.index;
        });
    }

    getAxis2D(): THREE.Vector2 {
        const axis = new THREE.Vector2(0, 0);

        // Keyboard (WASD / Arrows)
        if (this.keys.has('ArrowLeft') || this.keys.has('KeyA')) axis.x -= 1;
        if (this.keys.has('ArrowRight') || this.keys.has('KeyD')) axis.x += 1;
        if (this.keys.has('ArrowUp') || this.keys.has('KeyW')) axis.y += 1;
        if (this.keys.has('ArrowDown') || this.keys.has('KeyS')) axis.y -= 1;

        // Gamepad (Left Stick)
        if (this.gamepadIndex !== null) {
            const gp = navigator.getGamepads()[this.gamepadIndex];
            if (gp) {
                const deadzone = 0.2;
                let lx = gp.axes[0];
                let ly = gp.axes[1];

                if (Math.abs(lx) < deadzone) lx = 0;
                if (Math.abs(ly) < deadzone) ly = 0;

                // Gamepad X is usually Right, so we map it to our horizontal axis
                axis.x += lx; 
                // Gamepad Y is usually Up/Down, inverted for standard "forward" feel
                axis.y -= ly; 
            }
        }

        return axis.normalize();
    }

    wasPressed(key: string): boolean {
        const pressed = this.keys.has(key);
        if (pressed) this.keys.delete(key); // Consume the press
        return pressed;
    }

    getGamepadButton(buttonIndex: number): boolean {
        if (this.gamepadIndex === null) return false;
        const gp = navigator.getGamepads()[this.gamepadIndex];
        return gp && gp.buttons[buttonIndex] ? gp.buttons[buttonIndex].pressed : false;
    }

    // Standard Gamepad Button Mappings: 0=South(B), 1=East(A), 2=West(X), 3=North(Y)
    getGamepadFire(): boolean {
        return this.getGamepadButton(0); 
    }
}
