import * as THREE from 'three';

export class CameraShake {
    private intensity = 0;
    private decay = 0.92; // Intensity multiplier per frame

    addImpact(velocity: number, position?: THREE.Vector3) {
        this.intensity += Math.min(velocity * 0.5, 2.0); // Cap impact contribution
    }

    update() {
        if (this.intensity > 0.01) {
            this.intensity *= this.decay;
        } else {
            this.intensity = 0;
        }
    }

    apply(camera: THREE.PerspectiveCamera) {
        if (this.intensity <= 0) return;

        const shakeX = (Math.random() - 0.5) * this.intensity;
        const shakeY = (Math.random() - 0.5) * this.intensity;

        camera.position.x += shakeX;
        camera.position.y += shakeY;
    }

    reset() {
        this.intensity = 0;
    }
}
