export function startGameLoop(updateFn: (dt: number) => void, renderFn: () => void): { stop(): void } {
    let lastTime = performance.now();
    let running = true;

    const loop = (time: number) => {
        if (!running) return;

        // Cap delta time to prevent physics explosions on tab-switch
        const rawDt = Math.min((time - lastTime) / 1000, 0.1); 
        lastTime = time;

        updateFn(rawDt);
        renderFn();

        requestAnimationFrame(loop);
    };

    requestAnimationFrame(loop);

    return {
        stop: () => { running = false; }
    };
}
