export class Pool<T> {
    private pool: T[] = [];
    private factory: () => T;
    private resetFn: (item: T) => void;

    constructor(factory: () => T, resetFn: (item: T) => void) {
        this.factory = factory;
        this.resetFn = resetFn;
    }

    acquire(): T {
        if (this.pool.length > 0) {
            const item = this.pool.pop()!;
            return item;
        }
        return this.factory();
    }

    release(item: T): void {
        this.resetFn(item);
        this.pool.push(item);
    }
}
