import * as THREE from 'three';

const MAX_PARTICLES = 500;

class Particle {
    position: THREE.Vector3;
    velocity: THREE.Vector3;
    color: THREE.Color;
    life: number;
    maxLife: number;
    mesh: THREE.Mesh<THREE.SphereGeometry, THREE.MeshBasicMaterial>;

    constructor() {
        this.position = new THREE.Vector3();
        this.velocity = new THREE.Vector3();
        this.color = new THREE.Color();
        this.life = 0;
        this.maxLife = 0;

        const geo = new THREE.SphereGeometry(0.2, 4, 4); // Low poly for performance
        const mat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        this.mesh = new THREE.Mesh(geo, mat);
    }

    init(pos: THREE.Vector3, vel: THREE.Vector3, col: THREE.Color) {
        this.position.copy(pos);
        this.velocity.copy(vel);
        this.color.copy(col);
        this.maxLife = 1.0 + Math.random() * 0.5; // 1-1.5s life
        this.life = this.maxLife;
        this.mesh.material.color.copy(this.color);
    }

    update(dt: number) {
        this.velocity.y -= 9.8 * dt; // Gravity
        this.position.addScaledVector(this.velocity, dt);
        this.life -= dt;

        if (this.life <= 0) return false; // Dead

        const alpha = Math.max(0, this.life / this.maxLife);
        this.mesh.material.opacity = alpha;
        this.mesh.visible = true;
        return true;
    }

    dispose() {
        this.mesh.geometry.dispose();
        this.mesh.material.dispose();
    }
}

export class ParticleManager {
    private particles: Particle[] = [];
    private activeCount = 0;

    constructor(private scene: THREE.Scene) {}

    burst(position: THREE.Vector3, count: number, color: THREE.Color) {
        for (let i = 0; i < count && this.activeCount < MAX_PARTICLES; i++) {
            const p = new Particle(); // In a real pool, we'd acquire from a pool here

            // Random velocity in sphere radius
            const vel = new THREE.Vector3(
                (Math.random() - 0.5) * 10,
                Math.random() * 10 + 2,
                (Math.random() - 0.5) * 10
            );

            p.init(position.clone(), vel, color);
            this.scene.add(p.mesh);

            // Store in array for update loop
            // Note: In a strict pool implementation, we'd manage the array differently. 
            // For simplicity in this step, we push to an active list and filter out dead ones.
            this.particles.push(p);
            this.activeCount++;
        }
    }

    update(dt: number) {
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const alive = this.particles[i].update(dt);
            if (!alive) {
                this.scene.remove(this.particles[i].mesh);
                this.particles[i].dispose();
                this.particles.splice(i, 1);
                this.activeCount--;
            }
        }
    }

    dispose() {
        for (const p of this.particles) {
            this.scene.remove(p.mesh);
            p.dispose();
        }
        this.particles = [];
    }
}
