export class TrailRenderer {
    private history: Map<THREE.Mesh, THREE.Vector3[]> = new Map();

    addEntity(mesh: THREE.Mesh, maxHistory: number) {
        this.history.set(mesh, []);
    }

    update(dt: number) {
        for (const [mesh, hist] of this.history.entries()) {
            if (!mesh.visible) continue; // Only track visible entities

            const pos = new THREE.Vector3();
            mesh.getWorldPosition(pos);

            hist.push(pos.clone());
            if (hist.length > 10) hist.shift(); // Keep last 10 frames approx at 60fps -> ~0.15s trail
        }
    }

    render(renderer: THREE.WebGLRenderer) {
        const material = new THREE.LineBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.3 });

        for (const [mesh, hist] of this.history.entries()) {
            if (hist.length < 2 || !mesh.visible) continue;

            const points = hist.map(p => p.clone()); // Copy to avoid reference issues during frame draw

