    const anim = setInterval(() => {
        updatePosition();
        worldPos.y += 2 * 0.016; // Float up
        opacity -= 0.02;
        el.style.opacity = String(opacity);

        if (opacity <= 0) {
            clearInterval(anim);
            el.remove();
        }
