import * as THREE from 'three';

export function createGrid(width: number, height: number, cellSize: number): THREE.LineSegments {
    const points = [];
    const halfW = width / 2;
    const halfH = height / 2;

    for (let x = -halfW; x <= halfW; x += cellSize) {
        points.push(new THREE.Vector3(x, 0, -halfH);
        points.push(new THREE.Vector3(x, 0, halfH));
    }
    for (let z = -halfH; z <= halfH; z += cellSize) {
        points.push(new THREE.Vector3(-halfW, 0, z);
        points.push(new THREE.Vector3(halfW, 0, z));
    }

    const geo = new THREE.BufferGeometry().setFromPoints(points);
    const mat = new THREE.LineBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.2 });

    return new THREE.LineSegments(geo, mat);
}
