import { LaserManager } from './systems/LaserManager.js';
import { BarrierSystem } from './systems/BarrierSystem.js';
import { MysteryShip } from './systems/MysteryShip.js';

class SpaceInvadersGame {
    private renderer: THREE.WebGLRenderer;
    private scene: THREE.Scene;
    private camera: THREE.PerspectiveCamera;
    private composer: any; // EffectComposer
    private input: InputManager;
    private audio: AudioEngine;
    private hud: GlassHUD;

    private shake: CameraShake;
    private hitStop: HitStop;
    private particles: ParticleManager;
    private shockwaves: ShockwaveManager;

    // Game Entities
    private grid: THREE.LineSegments;
    private playerShip: PlayerShip;
    private alienGrid: AlienGrid;
    private lasers: LaserManager;
    private barriers: BarrierSystem;
    private mysteryShip: MysteryShip | null = null;

    private wave = 1;
    private score = 0;
    private lives = 3;
    private gameActive = true;

    constructor() {
        const canvas = document.getElementById('game-canvas') as HTMLCanvasElement;

        // 1. Core Engine Init
        const { renderer, scene, camera } = createRenderer(canvas);
        this.renderer = renderer;
        this.scene = scene;
        this.camera = camera;

        this.composer = initPostProcessing(renderer, window.innerWidth, window.innerHeight);
        this.input = new InputManager();
        this.audio = new AudioEngine();
        this.hud = new GlassHUD();

        // 2. VFX Systems Init
        this.shake = new CameraShake();
        this.hitStop = new HitStop();
        this.particles = new ParticleManager(scene);
        this.shockwaves = new ShockwaveManager();

        // 3. Game World Setup
        this.grid = createGrid(60, 40, 2);
        this.scene.add(this.grid);

        // Dynamic Lighting
        const playerLight = new THREE.PointLight(0x00ffff, 2, 15);
        playerLight.position.set(0, 5, 0);
        this.scene.add(playerLight);

        const ambientLight = new THREE.AmbientLight(0x404060, 0.5); // Dim purple ambient
        this.scene.add(ambientLight);

        // 4. Game Systems Init
        this.playerShip = new PlayerShip(scene, playerLight);
        this.alienGrid = new AlienGrid(scene);
        this.lasers = new LaserManager(scene);
        this.barriers = new BarrierSystem(scene);
        this.mysteryShip = null;

        // 5. Start Loop
        startGameLoop(this.update.bind(this), this.render.bind(this));

        window.addEventListener('resize', () => resizeRenderer(renderer, scene, camera));
    }

    private update(dt: number) {
        if (!this.gameActive) return;

        // Hit Stop Logic (Freeze time on impact)
        dt = this.hitStop.update(dt);
        if (dt === 0) return; // Time is frozen, skip updates

        // Input & Player
        const axis = this.input.getAxis2D();
        this.playerShip.move(axis.x * 15, dt); // Speed 15 units/sec

        // Shooting
        if (this.input.wasPressed('Space') || this.input.getGamepadFire()) {
            this.lasers.firePlayerLaser(this.playerShip.mesh.position.clone());
            this.audio.playSfx('laser');
        }

        // Alien Logic
        const alienResult = this.alienGrid.update(dt, this.barriers);

        if (alienResult.hitBarrier) {
            this.shake.addImpact(2);
            this.particles.burst(alienResult.position, 5, new THREE.Color(0xff00ff));
        }

        // Alien Shooting
        if (Math.random() < 0.01 * this.alienGrid.getRemainingCount()) { // Rate scales with remaining aliens
             const pos = this.alienGrid.getRandomBottomAlienPosition();
             if (pos) this.lasers.fireAlienLaser(pos);
        }

        // Mystery Ship Logic
        if (!this.mysteryShip && Math.random() < 0.001) { // Rare spawn chance per frame
            this.mysteryShip = new MysteryShip(this.scene);
            this.audio.playSfx('mystery');
        }

        if (this.mysteryShip) {
            const hit = this.mysteryShip.update(dt, this.playerShip.mesh.position, this.alienGrid.getAlienPositions());
            if (hit === 'player') {
                this.lasers.destroyPlayerLaser(this.mysteryShip.mesh); // Remove mystery ship mesh from scene manually or via manager
                this.score += 100;
                this.hud.updateScore(this.score);
                showFloatingScore(new THREE.Vector3(0, 25, -10), 100);
                this.shake.addImpact(3);
                this.hitStop.trigger(5); // Freeze for 5 frames
            } else if (hit === 'alien') {
                this.score += 50;
                this.hud.updateScore(this.score);
                showFloatingScore(new THREE.Vector3(0, 25, -10), 50);
            } else if (hit === 'gone') {
                this.scene.remove(this.mysteryShip.mesh);
                this.mysteryShip = null;
            }
        }

        // Laser Updates & Collisions
        const laserUpdates = this.lasers.update(dt, this.playerShip.mesh.position.y, 20); // Top bound 20

        for (const update of laserUpdates) {
            if (update.type === 'alien_hit') {
                this.alienGrid.destroyAlienAt(update.pos);
                this.score += 10;
                this.hud.updateScore(this.score);
                showFloatingScore(update.pos, 10);
                this.shake.addImpact(1);
                this.particles.burst(update.pos.clone(), 8, new THREE.Color(0x00ff00));
                this.hitStop.trigger(2); // Micro freeze on kill
            } else if (update.type === 'player_hit') {
                this.lives--;
                this.hud.updateScore(this.score); // Just to refresh UI state maybe? No, lives handled elsewhere.
                document.getElementById('lives-val')!.textContent = String(this.lives); // Assuming we add a lives element

                if (this.lives <= 0) {
                    this.gameActive = false;
                    this.hud.gameOver(this.score);
                    this.audio.playSfx('explosion');
                } else {
                    this.shake.addImpact(5);
                    this.hitStop.trigger(10); // Big freeze on death
                }
            } else if (update.type === 'barrier_hit') {
                 this.barriers.damageBarrier(update.pos);
            }
        }

        // Win Condition
        if (this.alienGrid.getRemainingCount() === 0) {
            this.wave++;
            this.hud.updateWave(this.wave);
            this.alienGrid.reset(this.wave);
            this.barriers.regrow();
        }

        // VFX Updates
        this.shake.update();
        this.particles.update(dt);
    }

    private render() {
        this.camera.position.x += (Math.random() - 0.5) * this.shake.intensity;
        this.camera.position.y += (Math.random() - 0.5) * this.shake.intensity;

        // Reset camera to smooth out jitter if needed, or just let it shake
        // For retro feel, raw jitter is okay.

        this.composer.render();
    }
}

