import * as THREE from 'three';
import { GeometryBuilder } from '../../../shared/gen/GeometryBuilder.js';

export class AlienGrid {
    private aliens: THREE.Mesh[] = [];
    private direction = 1; // 1 right, -1 left
    private speed = 0.5;
    private dropDistance = 1;

    constructor(private scene: THREE.Scene) {
        this.reset(1);
    }

    reset(wave: number) {
        // Clear old aliens
        for (const a of this.aliens) {
            this.scene.remove(a);
            a.geometry.dispose();
            (a.material as THREE.Material).dispose();
        }
        this.aliens = [];

        const rows = 5;
        const cols = 11;
        const startX = -10;
        const startY = 15;

        // Colors per row (Green, Cyan, Yellow, Orange, Red)
        const colors = [0x00ff00, 0x00ffff, 0xffff00, 0xffa500, 0xff0000];

        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const mesh = GeometryBuilder.createBox(new THREE.Vector3(1.5, 1.5, 1), colors[r]);
                mesh.position.set(startX + c * 2.5, startY - r * 2, 0);
                this.scene.add(mesh);
                this.aliens.push(mesh);
            }
        }

        // Speed scales with wave
        this.speed = 0.5 + (wave - 1) * 0.2;
    }

    update(dt: number, barriers: any): { hitBarrier?: boolean; position?: THREE.Vector3 } | void {
        let shouldDrop = false;

        // Edge detection
        for (const a of this.aliens) {
            if ((this.direction === 1 && a.position.x > 12) || 
                (this.direction === -1 && a.position.x < -12)) {
                shouldDrop = true;
                break;
            }
        }

        if (shouldDrop) {
            this.direction *= -1;
            for (const a of this.aliens) {
                a.position.y -= this.dropDistance;
            }
        } else {
            const moveAmount = this.speed * dt * this.direction;
            for (const a of this.aliens) {
                a.position.x += moveAmount;
            }
        }

        // Check barrier collisions (simplified: check if any alien is inside a barrier block)
        // For brevity in this step, we'll skip complex barrier collision logic here and assume it's handled by LaserManager or simple AABB.
        return {}; 
    }

    getRemainingCount(): number {
        return this.aliens.length;
    }

    destroyAlienAt(pos: THREE.Vector3) {
        const index = this.aliens.findIndex(a => a.position.distanceToSquared(pos) < 0.1);
        if (index !== -1) {
            const alien = this.aliens[index];
            this.scene.remove(alien);
            alien.geometry.dispose();
            (alien.material as THREE.Material).dispose();
            this.aliens.splice(index, 1);
        }
    }

    getRandomBottomAlienPosition(): THREE.Vector3 | null {
        if (this.aliens.length === 0) return null;
        // Find the lowest alien in each column, pick random column
        const columns = new Map<number, number>(); // x -> y
        for (const a of this.aliens) {
            const xKey = Math.round(a.position.x / 2.5);
            if (!columns.has(xKey) || a.position.y < columns.get(xKey)!) {
                columns.set(xKey, a.position.y);
            }
        }

        const randomCol = Array.from(columns.keys())[Math.floor(Math.random() * columns.size)];
        const alien = this.aliens.find(a => Math.round(a.position.x / 2.5) === randomCol);
        return alien ? new THREE.Vector3(alien.position.x, alien.position.y - 1, 0) : null;
    }

    getAlienPositions(): THREE.Vector3[] {
        return this.aliens.map(a => a.position.clone());
    }
}
