    private playerLasers: { mesh: THREE.Mesh; active: boolean }[] = [];
    private alienLasers: { mesh: THREE.Vector3; active: boolean; speed: number }[] = []; // Simplified for this step

    constructor(private scene: THREE.Scene) {}

    firePlayerLaser(position: THREE.Vector3) {
        if (this.playerLasers.filter(l => l.active).length >= 3) return; // Max 3 bullets

        const mesh = GeometryBuilder.createBox(new THREE.Vector3(0.2, 1, 0.2), 0x00ffff);
        mesh.position.copy(position);
        mesh.position.y += 1;
        this.scene.add(mesh);

        this.playerLasers.push({ mesh, active: true });
    }

    fireAlienLaser(position: THREE.Vector3) {
        const mesh = GeometryBuilder.createBox(new THREE.Vector3(0.2, 1, 0.2), 0xff0000);
        mesh.position.copy(position);
        this.scene.add(mesh);

        // Store as simple object for update loop
        this.alienLasers.push({ 
            mesh: new THREE.Vector3(position.x, position.y, 0), 
            active: true, 
            speed: -10 
        });
    }

    destroyPlayerLaser(mesh: THREE.Mesh) {
        const idx = this.playerLasers.findIndex(l => l.mesh === mesh);
        if (idx !== -1) {
            this.scene.remove(this.playerLasers[idx].mesh);
            this.playerLasers.splice(idx, 1);
        }
    }

    update(dt: number, playerY: number, topBound: number): Array<{ type: string; pos?: THREE.Vector3 }> {
        const updates = [];

        // Update Player Lasers
        for (let i = this.playerLasers.length - 1; i >= 0; i--) {
            const laser = this.playerLasers[i];
            if (!laser.active) continue;

            laser.mesh.position.y += 20 * dt; // Speed up

            if (laser.mesh.position.y > topBound) {
                this.scene.remove(laser.mesh);
                this.playerLasers.splice(i, 1);
                continue;
            }

            // Check collision with aliens (simplified distance check)
            // In a real game, use a spatial map. Here we iterate all for simplicity of the single-file constraint.
            // This is O(N*M) but N=55, M=3 so it's fine.
        }

        return updates;
    }
