import * as THREE from 'three';
import { GeometryBuilder } from '../../../shared/gen/GeometryBuilder.js';

export class BarrierSystem {
    private blocks: { mesh: THREE.Mesh; active: boolean }[] = [];

    constructor(scene: THREE.Scene) {
        this.regrow();
    }

    regrow() {
        // Clear old
        for (const b of this.blocks) scene.remove(b.mesh);
        this.blocks = [];

        const positions = [
            [-15, -20], [-5, -20], [5, -20], [15, -20] // 4 barriers
        ];

        for (const [x, y] of positions) {
            // Classic barrier shape: 3x3 grid with gaps
            const offsets = [
                [-0.5, 0.5], [0, 0.5], [0.5, 0.5],
                [-0.5, 0], [0.5, 0],
                [-0.5, -0.5], [0, -0.5], [0.5, -0.5]
            ];

            for (const [ox, oy] of offsets) {
                const mesh = GeometryBuilder.createBox(new THREE.Vector3(1, 1, 0.5), 0x00ff00);
                mesh.position.set(x + ox, y + oy, 0);
                scene.add(mesh);
                this.blocks.push({ mesh, active: true });
            }
        }
    }

    damageBarrier(pos: THREE.Vector3) {
        // Find closest block and deactivate it
        let closest = null;
        let minDist = Infinity;

        for (const b of this.blocks) {
            if (!b.active) continue;
            const d = b.mesh.position.distanceToSquared(pos);
            if (d < 1 && d < minDist) { // Proximity check
                closest = b;
                minDist = d;
            }
        }

        if (closest) {
            this.scene.remove(closest.mesh);
            closest.active = false;
        }
    }
}
